# 패턴 1: 투 포인터 — 정렬 배열에서 합이 target인 두 수의 인덱스
def two_sum_sorted(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        s = arr[left] + arr[right]
        if s == target:
            return (left, right)
        elif s < target:
            left += 1   # 합이 작으니 왼쪽 포인터를 오른쪽으로
        else:
            right -= 1  # 합이 크니 오른쪽 포인터를 왼쪽으로
    return None

arr = [1, 3, 5, 7, 9, 11]
print(two_sum_sorted(arr, 10))  # (1, 4) — 3+7이 아닌 3+9=12, 1+9=10!
# arr[1]=3, arr[4]=9, 3+9=12 → right-- → arr[1]=3, arr[3]=7, 3+7=10!

# 패턴 2: 접두사 합 — 구간 합을 O(1)에 계산
def build_prefix(arr):
    prefix = [0] * (len(arr) + 1)
    for i, v in enumerate(arr):
        prefix[i + 1] = prefix[i] + v
    return prefix

def range_sum(prefix, l, r):  # arr[l..r] 합, O(1)
    return prefix[r + 1] - prefix[l]

arr2 = [3, 1, 4, 1, 5, 9, 2, 6]
prefix = build_prefix(arr2)
print(range_sum(prefix, 2, 5))  # arr2[2]+[3]+[4]+[5] = 4+1+5+9 = 19

